INSERT INTO pocapp.employee_income (emp_id, seq_no, currency_code, salary_amount)
SELECT e.emp_id, v.seq_no, v.currency_code, v.salary_amount
  FROM pocapp.employee e JOIN (
    SELECT '40000014' AS pid, 4 AS seq_no, 'DKK' AS currency_code, 0 AS salary_amount FROM dual
    UNION ALL
