-- Assert. A seed that half-loads under /container-entrypoint-initdb.d fails
-- silently; the first symptom would otherwise be an acceptance test reporting a
-- wrong value on a record that does not exist. Fail here instead, loudly.
SET SERVEROUTPUT ON
DECLARE
  PROCEDURE assert_count(p_table VARCHAR2, p_expected NUMBER) IS
    v_actual NUMBER;
  BEGIN
    EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM pocapp.' || p_table INTO v_actual;
    IF v_actual <> p_expected THEN
      RAISE_APPLICATION_ERROR(-20001,
        'SEED FAILED: pocapp.' || p_table || ' has ' || v_actual ||
        ' rows, expected ' || p_expected);
    END IF;
    DBMS_OUTPUT.PUT_LINE('  seed OK: ' || RPAD(p_table, 24) || v_actual || ' rows');
  END;
BEGIN
  assert_count('employee',              1107);
  assert_count('employee_address_line', 2441);
  assert_count('employee_language',     1813);
  assert_count('employee_income',       3578);
  DBMS_OUTPUT.PUT_LINE('SEED COMPLETE: 8939 rows');
END;
/

EXIT;
